/**
 * Regenerates `.expo/types/router.d.ts` — expo-router's typed-routes
 * declaration for `router.push()`/`<Link href>` targets.
 *
 * Why this exists as a standalone script rather than "whatever `expo start`
 * happens to write": that file is generated by Metro's watch handler, lives
 * under the gitignored `.expo/`, and is never regenerated by `tsc`. The two
 * failure modes that produces are both silent:
 *
 *   - On a fresh checkout (CI) the file doesn't exist at all, so `Href`
 *     degrades to a permissive `string` and typed routes check nothing.
 *   - On a developer machine it exists but is however stale the last
 *     `expo start` left it, so routes added since (`/files`,
 *     `/notifications`) are reported as invalid targets — a type error in
 *     correct code, which CI can't reproduce.
 *
 * Wiring this into `pnpm type-check` makes both cases impossible: the
 * declaration is always regenerated from the current `app/` tree first.
 *
 * Caveat for whoever upgrades Expo: the three requires below reach into
 * expo-router's build output, not its public API — there is no CLI entry
 * point for typegen on SDK 52 (`expo start` does it from Metro's watch
 * handler). If an upgrade moves them, this script fails loudly and takes
 * `type-check` with it; that's deliberate, since skipping silently is what
 * produced the stale-declaration problem in the first place. `expo-router`'s
 * own `build/typed-routes/index.js` is the thing to re-read.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const MOBILE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const APP_ROOT = resolve(MOBILE_ROOT, "app");
const OUTPUT = resolve(MOBILE_ROOT, ".expo/types/router.d.ts");

// expo-router reads the app root from this env var rather than taking it as
// an argument -- it normally comes from @expo/cli's Metro config.
process.env.EXPO_ROUTER_APP_ROOT = APP_ROOT;

const { getTypedRoutesDeclarationFile } = require(
  "expo-router/build/typed-routes/generate",
);
const requireContext = require(
  "expo-router/build/testing-library/require-context-ponyfill",
).default;
const { EXPO_ROUTER_CTX_IGNORE } = require("expo-router/_ctx-shared");

const declaration = getTypedRoutesDeclarationFile(
  requireContext(APP_ROOT, true, EXPO_ROUTER_CTX_IGNORE),
  {},
);
if (!declaration) {
  throw new Error(
    `expo-router produced no typed-routes declaration for ${APP_ROOT}`,
  );
}

mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT, declaration);
